INSERT INTO company_dossiers (ticker,status,description,lede,sells,revenue_model,opportunity,must_go_right,editor_note,bull_title,bull_json,bear_title,bear_json,thesis_breaker,financial_drivers_json,risks_json,monitor_json,questions_json,competitors,evidence_date,validated_at,published_at,updated_at) VALUES
('ASUR','published','Cloud software company providing payroll, human-resources and workforce-compliance services to small and midsize employers.','Asure combines recurring payroll and human-capital-management software with tax, benefits, HR and managed services. Retention, attach rates, payroll volume, regulatory execution, acquisition integration and cash conversion determine whether growth creates owner value.','Payroll processing, tax filing, time and attendance, HR, benefits administration, recruiting and related workforce services.','Recurring subscription and processing fees, employee- or transaction-based charges, and professional or implementation services; acquisitions can add customers and products.','Small employers can consolidate fragmented payroll and compliance work onto a broader platform, increasing recurring revenue and products per client.','Asure must retain clients, process payroll and taxes accurately, protect sensitive data, integrate acquired resellers and convert recurring growth into durable free cash flow.','Separate organic recurring growth from acquired revenue. Track client retention, products per client, payroll funds, gross margin, acquisition consideration, debt, stock issuance and operating cash.','A broader compliance platform can deepen long-lived client relationships','["Payroll and tax compliance are recurring, mission-critical workflows.","Cross-selling HR, benefits and managed services can increase revenue per client.","A fragmented reseller market can support disciplined consolidation."]','Acquisition, processing and financing risk can offset headline growth','["Integration or client attrition can impair acquired economics.","Payroll or tax-processing errors and cyber incidents can create direct liabilities.","Debt and equity financing can dilute the benefit of recurring-revenue growth."]','The thesis breaks if organic retention and cash conversion remain weak while acquisitions, debt or dilution drive most reported growth','[{"label":"RECURRING GROWTH","value":"Demand quality","detail":"Organic revenue, retention, payroll clients, employees served and products per client"},{"label":"UNIT ECONOMICS","value":"Operating proof","detail":"Gross margin, service cost, sales efficiency and operating cash"},{"label":"CAPITAL ALLOCATION","value":"Owner outcome","detail":"Acquisition price, integration, debt, shares and free cash flow"}]','[{"title":"Payroll and compliance execution","level":"High","text":"Errors can create customer, regulatory and financial liabilities.","signal":"Tax notices, remediation, client losses and legal reserves"},{"title":"Cybersecurity and privacy","level":"High","text":"The platform handles payroll, banking and employee data.","signal":"Incidents, control findings and insurance costs"},{"title":"Acquisition and financing","level":"High","text":"Purchased growth may require leverage or dilution and prove difficult to integrate.","signal":"Organic growth, earnouts, debt and diluted shares"}]','[{"title":"Organic retention","text":"Require recurring growth supported by retained clients and greater product use.","impact":"BULL CASE"},{"title":"Cash after acquisitions","text":"Reconcile adjusted results with acquisition payments, interest, stock compensation and free cash flow.","impact":"NEUTRAL"}]','["How much recurring growth is organic rather than acquired?","What is client retention by cohort and how many products does each client use?","Does operating cash cover integration, debt service and further acquisitions?"]','ADP, Paychex, Paycom, Paylocity, UKG and other payroll or HR platforms.','2026-02-26','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASYS','published','Semiconductor-equipment company supplying thermal-processing, wafer-preparation and consumable products.','Amtech sells equipment and consumables used in advanced packaging, electronics assembly and silicon or silicon-carbide substrate fabrication. Orders, backlog conversion, customer capital spending, factory utilization and product mix drive results.','Reflow and thermal-processing systems, diffusion furnaces, wafer lapping and polishing equipment, carriers, templates, chemicals and related service.','Capital-equipment sales plus recurring consumables, spare parts and service; revenue depends on shipment, installation and customer acceptance.','AI-related advanced packaging, power semiconductors and more complex substrates can increase demand for thermal and wafer-processing steps.','Amtech must turn design wins and orders into accepted systems, stabilize operations, protect specialized know-how and earn returns through semiconductor cycles.','Backlog is not cash. Track order quality, cancellations, shipment timing, customer acceptance, segment mix, consumables attach, gross margin, inventory and diluted shares.','Advanced packaging can lift demand for specialized process equipment','["AI accelerators require increasingly complex packaging and thermal steps.","Consumables and service can add repeat revenue to installed equipment.","Focused brands address distinct wafer and electronics processes."]','Small scale and semiconductor cyclicality can produce sharp volatility','["Customer capex delays can reduce orders and backlog conversion.","Specialized product lines may face customer and supplier concentration.","Inventory, restructuring and capital raises can erode per-share returns."]','The thesis breaks if advanced-packaging demand does not translate into sustained profitable orders and positive free cash flow','[{"label":"ORDERS / BACKLOG","value":"Demand proof","detail":"Bookings, cancellations, backlog, shipment and acceptance timing"},{"label":"MIX / MARGIN","value":"Economic proof","detail":"Equipment, consumables, service, utilization and gross margin"},{"label":"CASH / SHARES","value":"Owner outcome","detail":"Working capital, capex, restructuring, financing and diluted shares"}]','[{"title":"Semiconductor cycle","level":"High","text":"Capital-equipment demand can change quickly with customer utilization and investment.","signal":"Orders, backlog revisions and lead times"},{"title":"Execution and concentration","level":"High","text":"A limited set of products, customers and suppliers increases operational sensitivity.","signal":"Acceptance delays, customer mix and warranty costs"},{"title":"Liquidity and dilution","level":"Medium","text":"Losses or expansion can require external capital.","signal":"Cash burn, offerings and share count"}]','[{"title":"Order conversion","text":"Track each major order through shipment, acceptance and cash collection.","impact":"BULL CASE"},{"title":"Cycle-normalized margin","text":"Test whether gross margin and cash flow remain viable at lower equipment volume.","impact":"NEUTRAL"}]','["Which products are gaining durable share in advanced packaging?","How much backlog is cancellable or dependent on customer acceptance?","Can consumables and service support profitability through a downcycle?"]','Larger semiconductor-equipment vendors and specialized thermal-processing, wafer-finishing and electronics-assembly suppliers.','2025-12-10','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATAI','published','Clinical-stage biotechnology company developing rapid-acting treatments for serious mental-health disorders.','AtaiBeckley advances psychedelic and other neuropsychiatric programs intended to deliver robust and durable benefit. Controlled clinical evidence, durability, safety, treatment logistics, regulatory alignment, intellectual property and transaction status drive value.','Investigational mental-health therapies, including clinical programs for depression and related neuropsychiatric conditions.','Before approval, the company has no durable product-sales model and depends on research partnerships, licensing, milestones and external capital; approved therapies could generate product revenue.','Large treatment-resistant populations create room for therapies that act faster or last longer than conventional care.','Programs must show reproducible benefit over placebo, manageable safety, practical administration and durability sufficient to justify supervised treatment and reimbursement.','Require complete trial protocols and patient-level outcomes. Track blinding, control response, durability, adverse events, therapy-session burden, cash runway, collaboration rights and any announced strategic transaction through closing.','Durable clinical benefit could establish a new treatment category','["Severe mental-health conditions retain substantial unmet need.","Rapid-acting mechanisms may help patients who fail conventional therapy.","Multiple programs provide more than one route to clinical proof."]','Clinical interpretation and commercialization logistics remain unusually difficult','["Expectancy and functional unblinding can complicate trial results.","Supervised administration may constrain capacity, reimbursement and adoption.","Development losses and strategic uncertainty can limit standalone owner value."]','The thesis breaks if controlled trials fail to show durable, clinically meaningful benefit with a feasible safety and delivery model','[{"label":"CONTROLLED EFFICACY","value":"Clinical proof","detail":"Effect size, placebo response, multiplicity, missing data and subgroup consistency"},{"label":"DURABILITY / DELIVERY","value":"Real-world fit","detail":"Time to response, relapse, repeat dosing, monitoring and therapy burden"},{"label":"RUNWAY / RIGHTS","value":"Owner outcome","detail":"Cash burn, trial cost, program rights, dilution and transaction terms"}]','[{"title":"Clinical design","level":"High","text":"Blinding, subjective endpoints and control response can distort apparent efficacy.","signal":"Protocol, sensitivity analyses and independent replication"},{"title":"Safety and regulation","level":"High","text":"Psychoactive treatments may require intensive monitoring and risk-management controls.","signal":"Serious events, FDA feedback and administration requirements"},{"title":"Financing and transaction","level":"High","text":"Long trials require capital and corporate transactions may alter residual value.","signal":"Runway, deal conditions, termination rights and diluted shares"}]','[{"title":"Decisive trial evidence","text":"Evaluate complete randomized results, durability and functional outcomes rather than topline claims.","impact":"BULL CASE"},{"title":"Delivery economics","text":"Model clinician time, treatment setting, reimbursement and repeat dosing.","impact":"NEUTRAL"}]','["What result would remain persuasive after accounting for functional unblinding?","How durable is benefit without repeated supervised dosing?","What value and risks remain for shareholders under the current transaction structure?"]','Compass Pathways, GH Research, MindMed, Cybin and established pharmaceutical treatments for depression and anxiety.','2026-03-06','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATEC','published','Medical-technology company developing procedural approaches, implants and information systems for spine surgery.','ATEC combines spinal implants, instruments, access systems, imaging and surgical-planning technology. Procedure growth, surgeon adoption, clinical outcomes, revenue per case, gross margin, debt and operating cash determine value.','Spinal implants and biologics, surgical instruments and access systems, EOS imaging, planning software and related services.','Product sales tied primarily to surgical procedures and imaging-system placements, with service and software elements around installed technology.','Integrated planning, positioning, imaging and implants can increase surgeon adoption and capture more value per spine procedure.','ATEC must demonstrate clinical distinction, train surgeons, supply complete procedure sets, gain reimbursement, manage product liability and fund growth without excessive leverage or dilution.','Do not equate surgeon interest with durable utilization. Track active surgeons, procedures per surgeon, revenue per case, implant and EOS mix, gross margin, inventory, stock compensation, debt and free cash flow.','An integrated procedural platform can compound surgeon adoption','["A coordinated approach can reduce friction across planning, access and implants.","Training and data can deepen surgeon familiarity with the platform.","A larger installed base can support recurring procedure revenue."]','High growth can remain capital intensive and competitively fragile','["Large spine competitors have broad portfolios and established hospital relationships.","Inventory, instrument sets and sales coverage consume substantial capital.","Debt, stock compensation and product-liability exposure can dilute operating progress."]','The thesis breaks if procedure and surgeon growth fail to produce sustainable positive free cash flow and improving per-share economics','[{"label":"PROCEDURE ADOPTION","value":"Demand proof","detail":"Active surgeons, procedures per surgeon, revenue per case and retention"},{"label":"GROSS PROFIT","value":"Economic proof","detail":"Implant, biologic, imaging and service mix, pricing and gross margin"},{"label":"CAPITAL INTENSITY","value":"Owner outcome","detail":"Inventory, instrument sets, sales expense, debt, stock compensation and cash"}]','[{"title":"Competitive adoption","level":"High","text":"Hospitals and surgeons may retain established vendors or use multiple systems.","signal":"Surgeon retention, procedure growth and price"},{"title":"Clinical and product liability","level":"High","text":"Device failures, adverse outcomes or recalls can harm patients and adoption.","signal":"Complaints, recalls, litigation and clinical evidence"},{"title":"Leverage and cash burn","level":"High","text":"Rapid expansion requires inventory, instruments and a specialized sales force.","signal":"Free cash flow, debt covenants and diluted shares"}]','[{"title":"Surgeon cohorts","text":"Measure repeat utilization and procedures per trained surgeon over time.","impact":"BULL CASE"},{"title":"Cash conversion","text":"Require growth to exceed the inventory, instrument, sales and financing burden.","impact":"NEUTRAL"}]','["Are new surgeons becoming repeat high-volume users?","Which integrated technologies measurably improve clinical or workflow outcomes?","When does operating growth translate into durable free cash flow per share?"]','Medtronic, Globus Medical, Stryker, Zimmer Biomet and DePuy Synthes.','2026-02-24','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATEN','published','Network-security and application-delivery company serving enterprises, service providers and cloud operators.','A10 Networks sells software and appliances that keep applications available, secure and efficient across data centers and networks. Subscription mix, installed-base renewal, cybersecurity demand, product execution and cash returns drive value.','Application-delivery controllers, DDoS defense, carrier-grade networking, encrypted-traffic visibility, management software and support.','Appliance and software-license sales plus recurring subscriptions, maintenance and support, often distributed through channel partners.','More encrypted traffic, distributed applications, AI infrastructure and cyber threats can expand demand for high-performance application security.','A10 must keep pace with cloud architectures and attacks, prove software renewal economics, protect its own products and maintain performance advantages against larger vendors.','Track recurring revenue and renewal separately from appliances. Monitor deferred revenue, subscription mix, billings, product gross margin, customer concentration, R&D, cash conversion, dividends and repurchases.','Security plus application performance can support durable renewal economics','["Application availability and DDoS protection are mission critical.","Software subscriptions and support can increase recurring revenue.","High-performance networking expertise can matter as traffic and encryption grow."]','Architecture shifts and larger competitors can compress the moat','["Customers may move functions into cloud-native or bundled platforms.","Product vulnerabilities or slow response to new threats can damage trust.","Service-provider and channel spending can be concentrated and cyclical."]','The thesis breaks if recurring software growth cannot offset appliance pressure and the company loses relevance in cloud and AI-era architectures','[{"label":"RECURRING MIX","value":"Revenue quality","detail":"Subscriptions, support, renewals, deferred revenue and billings"},{"label":"PRODUCT RELEVANCE","value":"Competitive proof","detail":"Security wins, performance, cloud deployment and customer retention"},{"label":"CASH RETURNS","value":"Owner outcome","detail":"Gross margin, R&D, free cash flow, dividends and repurchases"}]','[{"title":"Technology displacement","level":"High","text":"Cloud-native and bundled security services can replace dedicated products.","signal":"Renewals, software mix and competitive losses"},{"title":"Cybersecurity and defects","level":"High","text":"Vulnerabilities in security products can create reputational and legal harm.","signal":"Advisories, patches, incidents and support costs"},{"title":"Customer and channel concentration","level":"Medium","text":"Large service providers or distributors can change purchasing quickly.","signal":"Top-customer mix, channel inventory and receivables"}]','[{"title":"Renewal cohort","text":"Track subscription and support retention across the installed base.","impact":"BULL CASE"},{"title":"Cloud relevance","text":"Require evidence that products remain necessary in hybrid, edge and AI workloads.","impact":"NEUTRAL"}]','["How much growth comes from recurring software versus hardware refresh?","Which workloads require A10 rather than a bundled cloud or firewall service?","Are repurchases creating per-share value after stock compensation?"]','F5, NetScaler, Radware, Cloudflare, Palo Alto Networks and other application-security vendors.','2026-02-25','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATEX','published','Spectrum company licensing 900 MHz broadband rights and supporting private wireless networks for utilities.','Anterix owns licensed 900 MHz spectrum and seeks to monetize it through long-duration utility agreements and an ecosystem for private broadband networks. Contract timing, coverage, regulatory rights, cash collection and capital returns dominate value.','Licensed 900 MHz broadband spectrum rights, utility deployment support and an ecosystem of network technology partners.','Upfront and scheduled consideration from spectrum-use agreements, sales or leases; reported revenue and cash can be highly lumpy because utility contracts are negotiated individually.','Utilities need secure, resilient and controlled communications for grid modernization, creating a specialized use case for private broadband.','Anterix must sign utilities at attractive economics, clear incumbent users, preserve FCC rights, support deployments and return excess capital without undermining coverage value.','Treat announced contract value carefully. Track enforceable payments, timing, MHz-pop transferred, clearing obligations, cash taxes, operating burn, remaining spectrum and repurchases per share.','Scarce utility-suitable spectrum can support long-duration contracts','["Licensed low-band spectrum has favorable coverage characteristics.","Utilities value resilient, customer-controlled communications.","Each deployment can strengthen a compatible equipment ecosystem."]','Contract timing and asset monetization are concentrated and irregular','["Utility procurement and regulatory processes can take years.","Spectrum value depends on location, clearing cost and FCC conditions.","Large capital returns can reduce strategic flexibility if contracting slows."]','The thesis breaks if signed cash proceeds and remaining spectrum value fail to cover operating costs and justify the per-share valuation','[{"label":"CONTRACTED CASH","value":"Monetization proof","detail":"Signed agreements, payment schedule, conditions and collections"},{"label":"SPECTRUM INVENTORY","value":"Residual asset","detail":"MHz-pop, geography, clearing status, regulatory term and utility demand"},{"label":"PER-SHARE VALUE","value":"Owner outcome","detail":"Cash, taxes, operating burn, repurchases and diluted shares"}]','[{"title":"Contract concentration","level":"High","text":"A small number of large utility negotiations drive outcomes.","signal":"Signed contracts, delays, conditions and customer concentration"},{"title":"Regulatory and clearing","level":"High","text":"FCC rules and incumbent relocation affect usable rights and cost.","signal":"License actions, clearing milestones and interference"},{"title":"Capital allocation","level":"High","text":"Buybacks or distributions may precede slower-than-expected monetization.","signal":"Cash balance, burn, commitments and shares retired"}]','[{"title":"Cash-contract bridge","text":"Reconcile announced value with binding terms, collections and remaining obligations.","impact":"BULL CASE"},{"title":"Residual spectrum map","text":"Value unsold spectrum by market, usability, clearing cost and credible demand.","impact":"NEUTRAL"}]','["How much contracted consideration is unconditional and when is it collected?","What clearing and deployment obligations remain for each utility?","How much per-share value remains after taxes, burn and capital returns?"]','Commercial wireless carriers, shared-network services and alternative private-wireless spectrum or technologies.','2026-06-25','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATI','published','Producer of high-performance specialty materials for aerospace, defense and other demanding applications.','ATI melts, forges, rolls and finishes titanium, nickel-based superalloys and other advanced materials used where heat, strength, corrosion resistance and reliability matter. Long-cycle demand, qualification, capacity, yield, pricing and cash returns drive value.','Titanium and nickel alloys, specialty steels, forgings, castings, precision components and engineered material solutions.','Product sales under spot, index-linked and long-term customer agreements, with economics shaped by volume, mix, raw-material pass-through, yield and plant utilization.','Aerospace engine and airframe production, defense programs and difficult operating environments can increase demand for qualified specialty materials.','ATI must execute capacity investments, meet stringent certifications, secure raw materials, improve yield and deliver reliably into long-cycle customer programs.','Backlog can include schedule and price assumptions. Track aerospace and defense mix, customer commitments, melt and forging capacity, yield, premium pricing, working capital, capex and free cash flow.','Qualified materials capacity can become a durable aerospace bottleneck','["Material qualification and process know-how create high switching costs.","Aerospace and defense platforms can generate long production lives.","Tight specialty capacity can support favorable mix and pricing."]','Capital intensity and customer concentration can magnify execution errors','["Large aerospace customers and programs influence demand and terms.","Plant outages, quality escapes or delayed expansions can destroy margin.","Raw-material and labor constraints can absorb cash before new capacity earns returns."]','The thesis breaks if major capacity investments fail to produce qualified volume, stable margins and free cash flow across the aerospace cycle','[{"label":"AEROSPACE VOLUME","value":"Demand proof","detail":"Engine and airframe schedules, backlog, customer releases and mix"},{"label":"CAPACITY / YIELD","value":"Operating proof","detail":"Melt, forge and finish throughput, qualification, downtime and scrap"},{"label":"CASH RETURNS","value":"Owner outcome","detail":"Price-cost, working capital, capex, free cash flow and diluted shares"}]','[{"title":"Aerospace concentration","level":"High","text":"Customer or platform disruptions can change long-cycle demand.","signal":"Build rates, order changes and customer inventory"},{"title":"Operational execution","level":"High","text":"Complex plants face outage, quality and qualification risk.","signal":"Yield, downtime, warranty and delayed certification"},{"title":"Raw materials and capital","level":"High","text":"Inputs and expansion require substantial working and fixed capital.","signal":"Inventory, capex, inflation and free cash flow"}]','[{"title":"Qualified throughput","text":"Measure accepted aerospace volume from each expansion rather than nameplate capacity.","impact":"BULL CASE"},{"title":"Free cash after growth","text":"Require premium mix and yield to fund capex and strengthen per-share value.","impact":"NEUTRAL"}]','["Which customer programs support committed multi-year volume?","What utilization and yield are required for expansion returns?","How much free cash remains after working capital and strategic capex?"]','Carpenter Technology, Precision Castparts, Howmet Aerospace and other specialty-alloy or forged-component suppliers.','2026-02-20','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATKR','published','Manufacturer of electrical, safety and infrastructure products used in buildings, data centers, utilities and industrial projects.','Atkore produces conduit, cable-management, fittings, framing and related infrastructure products. Organic volume, price-cost, end-market demand, portfolio changes, legal exposure and free cash flow determine normalized owner earnings.','Electrical conduit and fittings, cable-management systems, metal framing, mechanical tube, safety and infrastructure products.','Product sales through distributors and project channels, with revenue driven by volume, market pricing, raw-material pass-through and product mix.','Electrification, data-center construction, grid investment and complex building infrastructure can support long-run demand.','Atkore must defend distribution positions, adapt capacity to normalized demand, manage commodity price-cost, resolve legal issues and allocate cash at attractive per-share returns.','Peak price and margin are not a base case. Track organic volume, price-cost, product and end-market mix, channel inventory, plant utilization, litigation, divestitures, capex, free cash flow and buybacks.','Scale and distribution can compound infrastructure demand','["A broad product set serves recurring electrical and safety needs.","Data centers and electrification can add structural demand.","Strong cash conversion can fund disciplined reinvestment and repurchases."]','Post-cycle normalization and legal risk can reset earnings power','["Commodity deflation and competition can reverse favorable pricing.","Construction and solar demand can weaken or shift channel inventory.","Antitrust or other litigation and poor buyback timing can impair capital returns."]','The thesis breaks if normalized volume and price-cost produce structurally lower free cash flow while legal and capital-allocation costs rise','[{"label":"VOLUME / PRICE-COST","value":"Normalized demand","detail":"Organic units, price, steel and resin cost, mix and channel inventory"},{"label":"END MARKETS","value":"Cycle exposure","detail":"Data center, commercial, industrial, utility, solar and residential demand"},{"label":"FREE CASH / CAPITAL","value":"Owner outcome","detail":"Capex, working capital, litigation, divestitures, dividends and repurchases"}]','[{"title":"Pricing normalization","level":"High","text":"Elevated spread and margins may compress as supply and input prices normalize.","signal":"Price-cost, gross margin and competitor capacity"},{"title":"Construction cycle","level":"High","text":"Project delays and distributor destocking can reduce volume.","signal":"Organic units, backlog and channel inventory"},{"title":"Legal and allocation","level":"High","text":"Litigation, acquisitions or buybacks can consume cash without adequate return.","signal":"Reserves, settlements, deal multiples and shares retired"}]','[{"title":"Normalized margin","text":"Underwrite earnings at through-cycle volume and commodity spreads.","impact":"NEUTRAL"},{"title":"Cash per share","text":"Track cumulative free cash against acquisition, litigation and repurchase spending.","impact":"BULL CASE"}]','["What margin is sustainable after price-cost normalizes?","How much data-center growth offsets softer construction or solar demand?","Have repurchases reduced shares at prices below conservative intrinsic value?"]','Eaton, Hubbell, nVent, ABB, Legrand and other electrical-infrastructure manufacturers.','2025-11-26','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATLC','published','Financial-technology company enabling bank partners to offer credit products to underserved consumers.','Atlanticus supplies technology, analytics, servicing and funding support for general-purpose cards, retail and healthcare credit, and automotive dealer programs. Credit performance, receivable growth, fair-value assumptions, funding cost, regulation and capital structure drive owner value.','Credit-card and point-of-sale programs, patient financing, servicing and analytics, plus dealer inventory and consumer-finance solutions.','Fees, finance-related income, servicing economics and fair-value changes tied to consumer receivables, funded through bank partnerships, securitizations, debt and other capital.','Proprietary underwriting data and partner distribution can expand responsible credit access to consumers underserved by prime lenders.','Atlanticus must price credit risk correctly, comply with consumer rules, retain bank and merchant partners, fund receivables through cycles and control leverage and senior claims.','Reported fair value depends on models. Track receivables, originations, delinquency, charge-offs, payment rates, yield, funding cost, fair-value marks, bank-partner concentration, debt, preferred claims and tangible equity.','Data and partner distribution can support profitable credit expansion','["Long operating history can improve underwriting and servicing decisions.","Bank, retail and healthcare partners provide embedded distribution.","Multiple credit products can diversify acquisition channels."]','Credit, funding and regulatory leverage can compound quickly','["Consumer stress can raise delinquencies and charge-offs faster than pricing adjusts.","Fair-value models rely on judgment about losses, payments, yields and discount rates.","Funding markets, bank partners and consumer regulators can constrain growth or capital returns."]','The thesis breaks if risk-adjusted receivable returns remain below funding and operating costs after realistic credit losses and senior capital claims','[{"label":"CREDIT VINTAGES","value":"Underwriting proof","detail":"Originations, delinquency, roll rates, charge-offs, recoveries and payment rates"},{"label":"RISK-ADJUSTED YIELD","value":"Economic proof","detail":"Fees and interest less credit loss, servicing, funding and partner costs"},{"label":"CAPITAL STACK","value":"Owner outcome","detail":"Securitizations, debt, preferreds, liquidity, fair-value marks and common equity"}]','[{"title":"Consumer credit","level":"High","text":"Underserved borrowers can be especially sensitive to employment and inflation.","signal":"Early delinquency, charge-offs and payment rates by vintage"},{"title":"Regulation and partners","level":"High","text":"Rules or bank-partner decisions can change product economics and availability.","signal":"Exams, enforcement, complaints and partner concentration"},{"title":"Funding and valuation","level":"High","text":"Leverage and model-based asset values can amplify adverse changes.","signal":"Advance rates, spreads, liquidity and fair-value sensitivities"}]','[{"title":"Vintage loss curves","text":"Compare each origination cohort with original loss and yield assumptions.","impact":"NEUTRAL"},{"title":"Common-equity coverage","text":"Stress receivables and funding before assigning value behind debt and preferred claims.","impact":"BEAR CASE"}]','["Are newer credit vintages seasoning within original loss expectations?","What net return remains after funding, servicing and normalized charge-offs?","How dependent is the platform on its largest bank and merchant partners?"]','Synchrony, OneMain, Capital One, Bread Financial and bank or fintech point-of-sale lenders.','2026-03-12','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATLO','published','Community-bank holding company operating locally managed banks in central Iowa.','Ames National earns primarily from the spread between loans and deposits across community banking franchises. Deposit stability, net interest margin, credit quality, securities valuation, capital and local economic conditions determine owner returns.','Commercial, agricultural, real-estate and consumer loans, deposits, treasury services and other community-banking products.','Net interest income from loans and securities funded by deposits, plus service charges, wealth-related and other fee income.','Locally empowered banks can build durable relationships, low-cost core deposits and disciplined credit knowledge in their communities.','The banks must retain deposits, price loans through rate cycles, control commercial and agricultural credit, manage securities duration and maintain capital while paying dividends.','Book value is not all equal. Track tangible common equity, accumulated unrealized securities losses, deposit mix and beta, uninsured deposits, net interest margin, nonperforming loans, criticized assets, charge-offs, capital and dividend coverage.','Local deposits and underwriting can create a durable community franchise','["Long-standing local relationships can support sticky core deposits.","Decentralized market knowledge can improve credit selection.","A conservative capital and dividend culture can compound tangible value."]','Rate, concentration and geographic risks can emerge together','["Deposit repricing can compress margin faster than assets reset.","Commercial real estate and agriculture concentrate exposure in central Iowa.","Securities losses and weak credit can limit capital flexibility and dividends."]','The thesis breaks if deposit franchise erosion and credit losses cause sustained decline in tangible book value and earning power per share','[{"label":"DEPOSIT FRANCHISE","value":"Funding quality","detail":"Core and uninsured deposits, mix, cost, beta and customer retention"},{"label":"CREDIT QUALITY","value":"Loss control","detail":"Loan mix, criticized assets, nonperformers, charge-offs and reserves"},{"label":"CAPITAL / BOOK","value":"Owner outcome","detail":"Tangible equity, securities marks, regulatory ratios, dividends and shares"}]','[{"title":"Interest-rate mismatch","level":"High","text":"Deposit costs and securities duration can pressure margin and equity.","signal":"Deposit beta, margin, duration and unrealized loss"},{"title":"Credit concentration","level":"High","text":"Local commercial, real-estate and agricultural weakness can correlate.","signal":"Criticized loans, collateral values and charge-offs"},{"title":"Geographic concentration","level":"Medium","text":"Central Iowa conditions affect borrowers, deposits and growth.","signal":"Farm income, employment and local property activity"}]','[{"title":"Deposit cohorts","text":"Track retention and repricing of core, brokered and uninsured deposits.","impact":"NEUTRAL"},{"title":"Tangible book durability","text":"Stress securities and loan losses against capital and dividend commitments.","impact":"BEAR CASE"}]','["How much deposit repricing remains under current rate scenarios?","Which loan concentrations drive criticized and nonperforming balances?","Can earnings and capital support the dividend without weakening tangible book value?"]','Iowa community and regional banks, credit unions and national banks serving the same markets.','2026-03-12','2026-08-05T09:09:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
